package main

import (
	"html/template"
	"log/slog"
	"net/http"
	"time"

	"github.com/example/noten/internal/calc"
)

var pageTemplates map[string]*template.Template

func init() {
	funcs := template.FuncMap{"avg": calc.Format, "cell": cell, "today": func() string { return time.Now().Format("2006-01-02") }}
	pageTemplates = map[string]*template.Template{
		loginHTML:   template.Must(template.New("login").Funcs(funcs).Parse(layout + loginHTML)),
		appHTML:     template.Must(template.New("app").Funcs(funcs).Parse(layout + appHTML)),
		gradeHTML:   template.Must(template.New("grade").Funcs(funcs).Parse(layout + gradeHTML)),
		studentHTML: template.Must(template.New("student").Funcs(funcs).Parse(layout + studentHTML)),
		historyHTML: template.Must(template.New("history").Funcs(funcs).Parse(layout + historyHTML)),
		trashHTML:   template.Must(template.New("trash").Funcs(funcs).Parse(layout + trashHTML)),
	}
}

func render(w http.ResponseWriter, p Page, body string) {
	t := pageTemplates[body]
	if t == nil {
		http.Error(w, "Darstellung nicht verfügbar", http.StatusInternalServerError)
		return
	}
	if err := t.ExecuteTemplate(w, "layout", p); err != nil {
		slog.Error("render failed", "error", err)
	}
}

const layout = `{{define "layout"}}<!doctype html><html lang="de"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><meta name="theme-color" content="#f7f7f5"><title>{{.Title}} · Noten</title><link rel="manifest" href="/static/app.webmanifest"><link rel="icon" href="/static/icons/icon.svg"><link rel="stylesheet" href="/static/app.css"><script defer src="/static/app.js"></script></head><body>{{if .Notice}}<aside class="undo-bar" data-undo-bar><span>{{.Notice}}</span>{{if .UndoID}}<form method="post" action="/changes/{{.UndoID}}/undo"><input type="hidden" name="return" value="/"><button>Rückgängig</button></form>{{end}}</aside>{{end}}{{template "body" .}}</body></html>{{end}}`
const loginHTML = `{{define "body"}}<main class="login"><form method="post" class="panel"><h1>Noten</h1><p class="muted">Privates Gradebook</p>{{if .Error}}<p class="error">{{.Error}}</p>{{end}}<label>Passwort<input name="password" type="password" required autofocus autocomplete="current-password"></label><button>Anmelden</button></form></main>{{end}}`
const appHTML = `{{define "body"}}<div class="shell"><aside><header><strong>Klassen</strong><form method="post" action="/logout"><button class="quiet">Abmelden</button></form></header><nav>{{range .Classes}}<a href="/?class={{.ID}}" {{if $.Class}}{{if eq .ID $.Class.ID}}class="active"{{end}}{{end}}>{{.Name}} <small>{{.Subject}}</small></a>{{end}}</nav><a class="trash-link" href="/trash">Gelöschte Elemente</a><details><summary>+ Klasse</summary><form method="post" action="/classes"><label>Name<input name="name" required></label><label>Fach<input name="subject"></label><button>Erstellen</button></form></details></aside><main class="workspace">{{if .Class}}<header class="top"><div><h1>{{.Class.Name}}</h1><span class="muted">{{.Class.Subject}}</span></div><button data-open="assessment">+ Leistung</button></header><div class="matrix"><table><thead><tr><th>Name</th>{{range .Assessments}}<th><a href="/assessments/{{.ID}}/grades">{{.Name}}</a><small>{{.Type}}</small></th>{{end}}<th>S</th><th>M</th><th>Ø</th></tr></thead><tbody>{{$page:=.}}{{range .Rows}}{{$row:=.}}<tr><th><a href="/students/{{.Student.ID}}">{{.Student.First}} {{.Student.Last}}</a></th>{{range $a:=$page.Assessments}}<td><a href="/assessments/{{$a.ID}}/grades?student={{$row.Student.ID}}">{{cell (index $row.Cells $a.ID)}}</a></td>{{end}}<td>{{avg .Result.Written}}</td><td>{{avg .Result.Oral}}</td><td class="overall">{{avg .Result.Overall}}</td></tr>{{else}}<tr><td colspan="99" class="empty">Noch keine Schüler. Über „Verwalten“ hinzufügen.</td></tr>{{end}}</tbody></table></div><details class="manage"><summary>Verwalten & Export</summary><div class="manage-grid"><form method="post" action="/classes/{{.Class.ID}}/edit"><h2>Klasse <a class="history-link" href="/history?type=class&entity={{.Class.ID}}">Verlauf</a></h2><label>Name<input name="name" value="{{.Class.Name}}" required></label><label>Fach<input name="subject" value="{{.Class.Subject}}"></label><label>Schriftlich %<input type="number" name="written" value="{{.Class.Written}}" min="0" max="100"></label><label>Mündlich %<input type="number" name="oral" value="{{.Class.Oral}}" min="0" max="100"></label><button>Speichern</button></form><form method="post" action="/classes/{{.Class.ID}}/students"><h2>Schüler hinzufügen</h2><label>Ein Name pro Zeile<textarea name="names" rows="6" required></textarea></label><button>Hinzufügen</button></form><section><h2>Schüler</h2>{{range .Students}}<form class="inline" method="post" action="/students/{{.ID}}/edit"><a class="history-link" href="/history?type=student&entity={{.ID}}">Verlauf</a><input name="first" value="{{.First}}" aria-label="Vorname"><input name="last" value="{{.Last}}" aria-label="Nachname"><button>Speichern</button><button class="danger" formaction="/students/{{.ID}}/delete" data-confirm="Schüler ausblenden? Vorhandene Noten bleiben erhalten und können wiederhergestellt werden.">Löschen</button></form>{{end}}</section><section><h2>Leistungen</h2>{{range .Assessments}}<form class="inline" method="post" action="/assessments/{{.ID}}/edit"><a class="history-link" href="/history?type=assessment&entity={{.ID}}">Verlauf</a><input name="name" value="{{.Name}}"><select name="type"><option value="written" {{if eq .Type "written"}}selected{{end}}>Klassenarbeit</option><option value="test" {{if eq .Type "test"}}selected{{end}}>Test</option><option value="oral" {{if eq .Type "oral"}}selected{{end}}>Mündlich</option></select><input name="date" type="date" value="{{.Date}}"><input name="weight" type="number" min="0.1" step="0.1" value="{{.Weight}}"><button>Speichern</button><button class="danger" formaction="/assessments/{{.ID}}/delete" data-confirm="Leistung ausblenden? Vorhandene Noten bleiben erhalten und können wiederhergestellt werden.">Löschen</button></form>{{end}}</section><p><a class="button" href="/classes/{{.Class.ID}}/export.csv">CSV exportieren</a></p><form method="post" action="/classes/{{.Class.ID}}/delete"><button class="danger" data-confirm="Klasse ausblenden? Alle Daten bleiben erhalten und können wiederhergestellt werden.">Klasse löschen</button></form></div></details><dialog id="assessment"><form method="post" action="/classes/{{.Class.ID}}/assessments"><header><h2>Neue Leistung</h2><button type="button" data-close aria-label="Schließen">×</button></header><label>Name<input name="name" required autofocus></label><label>Typ<select name="type" data-type><option value="test">Test</option><option value="written">Klassenarbeit</option><option value="oral">Mündliche Note</option></select></label><label>Datum<input name="date" type="date" value="{{today}}" required></label><label>Gewichtung<input name="weight" type="number" min="0.1" step="0.1" value="1" required></label><footer><button type="button" class="secondary" data-close>Abbrechen</button><button>Erstellen</button></footer></form></dialog>{{else}}<div class="welcome"><h1>Erste Klasse anlegen</h1><p>Lege links eine Klasse an und beginne direkt mit der Notenerfassung.</p></div>{{end}}</main></div>{{end}}`
const gradeHTML = `{{define "body"}}<main class="entry"><header class="top"><div><a href="/?class={{.Class.ID}}">← Matrix</a><h1>{{.Assessment.Name}}</h1><p class="muted">{{.Class.Name}} · {{.Assessment.Date}} · Gewicht {{.Assessment.Weight}}</p></div></header><div class="entry-grid"><ol class="student-list">{{range $i,$s:=.Students}}<li data-student="{{$s.ID}}" tabindex="0" role="button" {{if eq $s.ID $.ActiveStudent}}class="active"{{end}}><span>{{$s.First}} {{$s.Last}}</span><span><output id="grade-{{$s.ID}}">{{cell (index (index $.Rows $i).Cells $.Assessment.ID)}}</output><a class="history-link" href="/history?assessment={{$.Assessment.ID}}&student={{$s.ID}}">Verlauf</a></span></li>{{end}}</ol><section class="pad" aria-label="Notenfeld"><p id="entry-status">Note wählen – danach geht es automatisch weiter.</p><div><button data-grade="0">0</button><button data-grade="1">1</button><button data-grade="2">2</button><button data-grade="3">3</button><button data-grade="4">4</button><button data-grade="5">5</button><button data-grade="6">6</button><button data-grade="7">7</button><button data-grade="8">8</button><button data-grade="9">9</button><button data-grade="10">10</button><button data-grade="11">11</button><button data-grade="12">12</button><button data-grade="13">13</button><button data-grade="14">14</button><button data-grade="15">15</button></div><footer><button data-grade="absent" class="secondary">Fehlt</button><button data-grade="clear" class="secondary">Leeren</button></footer><form id="grade-form" hidden method="post" data-action="/assessments/{{.Assessment.ID}}/grades/"><input name="points"></form></section></div></main>{{end}}`
const studentHTML = `{{define "body"}}<main class="detail"><a href="/?class={{.Class.ID}}">← {{.Class.Name}}</a><h1>{{.Title}}</h1>{{$r:=index .Rows 0}}<div class="averages"><div><small>Gesamt</small><strong>{{avg $r.Result.Overall}}</strong></div><div><small>Schriftlich</small><strong>{{avg $r.Result.Written}}</strong></div><div><small>Mündlich</small><strong>{{avg $r.Result.Oral}}</strong></div></div><table><tbody>{{range .Assessments}}<tr><th>{{.Name}}<small>{{.Date}}</small></th><td>{{cell (index $r.Cells .ID)}}</td></tr>{{end}}</tbody></table></main>{{end}}`

const historyHTML = `{{define "body"}}<main class="detail"><a href="/">← Noten</a><h1>Änderungsverlauf</h1><table><thead><tr><th>Zeit</th><th>Aktion</th><th>Vorher</th><th>Nachher</th><th></th></tr></thead><tbody>{{range .History}}<tr><td>{{.CreatedAt}}</td><td>{{.Action}}</td><td><code>{{.Before}}</code></td><td><code>{{.After}}</code></td><td>{{if eq .EntityType "grade"}}<form method="post" action="/history/{{.ID}}/restore"><button class="secondary">Vorherigen Wert wiederherstellen</button></form>{{end}}</td></tr>{{else}}<tr><td colspan="5">Noch keine Änderungen.</td></tr>{{end}}</tbody></table></main>{{end}}`
const trashHTML = `{{define "body"}}<main class="detail"><a href="/">← Noten</a><h1>Gelöschte Elemente</h1><h2>Klassen</h2>{{range .Deleted.Classes}}<form class="restore-row" method="post" action="/trash/class/{{.ID}}/restore"><span>{{.Name}} <small>{{.Subject}}</small></span><button>Wiederherstellen</button></form>{{else}}<p class="muted">Keine gelöschten Klassen.</p>{{end}}<h2>Schüler</h2>{{range .Deleted.Students}}<form class="restore-row" method="post" action="/trash/student/{{.ID}}/restore"><span>{{.First}} {{.Last}}</span><button>Wiederherstellen</button></form>{{else}}<p class="muted">Keine gelöschten Schüler.</p>{{end}}<h2>Leistungen</h2>{{range .Deleted.Assessments}}<form class="restore-row" method="post" action="/trash/assessment/{{.ID}}/restore"><span>{{.Name}} <small>{{.Date}}</small></span><button>Wiederherstellen</button></form>{{else}}<p class="muted">Keine gelöschten Leistungen.</p>{{end}}</main>{{end}}`
